[
  {
    "title": "緩衝液的 pH 估算",
    "body": "緩衝液的 pH 約等於弱酸的 pKa 加上共軛鹼與弱酸濃度比的對數；兩者比例決定 pH。",
    "examples": ["若共軛鹼與弱酸濃度相等，pH 約等於該弱酸的 pKa。"]
  },
  {
    "title": "最佳緩衝比例",
    "body": "當弱酸與共軛鹼的量接近相等時，緩衝能力通常較佳；有效範圍約在 pKa 前後各 1 個 pH 單位。",
    "examples": ["弱酸的 pKa 為 4.8 時，pH 約 3.8～5.8 的緩衝效果較明顯。"]
  },
  {
    "title": "稀釋對緩衝液的影響",
    "body": "以水稀釋緩衝液時，弱酸與共軛鹼的比例近乎不變，所以 pH 變化小；但總濃度降低，抵抗加酸鹼的能力變弱。",
    "examples": ["將緩衝液加水稀釋十倍，pH 可近似維持，卻更容易被少量強酸改變。"]
  }
]
